using System;using System.Linq;using UnityEngine;using UnityEditor;using Codice.Characters;
public static class ReviewDetailedPoses{
 public static string Run(){var stage=new GameObject("Model verification");try{int count=0;var camera=new GameObject("Camera").AddComponent<Camera>();camera.transform.SetParent(stage.transform);camera.transform.position=new Vector3(2.8f,-2.1f,10f);camera.transform.LookAt(new Vector3(2.8f,-2.1f,0));camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=new Color(.1f,.12f,.15f);camera.orthographic=true;camera.orthographicSize=4.8f;camera.cullingMask=1<<29;var light=new GameObject("Key").AddComponent<Light>();light.transform.SetParent(stage.transform);light.type=LightType.Directional;light.intensity=2;light.transform.rotation=Quaternion.Euler(40,-145,0);light.cullingMask=1<<29;
 foreach(string action in new[]{"Idle","NativeRunForward","SwordCombo1","Dash"}) foreach(PlayerClass role in Enum.GetValues(typeof(PlayerClass))){var go=UnityEngine.Object.Instantiate(Resources.Load<GameObject>("Presentation/Classes/"+role),stage.transform);var animator=go.GetComponentInChildren<Animator>();if(!animator.avatar||!animator.avatar.isHuman||!animator.avatar.isValid)throw new Exception("Invalid Avatar "+role);animator.enabled=false;var clips=animator.runtimeAnimatorController.animationClips.Distinct();foreach(var clip in clips)for(int frame=0;frame<3;frame++){clip.SampleAnimation(go,clip.length*frame/3);foreach(var bone in new[]{HumanBodyBones.Head,HumanBodyBones.LeftHand,HumanBodyBones.RightHand,HumanBodyBones.LeftFoot,HumanBodyBones.RightFoot})if((animator.GetBoneTransform(bone).position-go.transform.position).magnitude>3.6f)throw new Exception("Invalid pose "+role+" "+clip.name);}
 var idle=clips.FirstOrDefault(x=>x.name==(role==PlayerClass.Berserker&&action=="SwordCombo1"?"DualSlice":action))??clips.First();idle.SampleAnimation(go,idle.length*.38f);go.transform.position=new Vector3((count%6)*1.1f,-(count/6)*2.2f,0);count++;foreach(var t in go.GetComponentsInChildren<Transform>())t.gameObject.layer=29;}
 var rt=new RenderTexture(1800,1800,24);camera.targetTexture=rt;camera.Render();var old=RenderTexture.active;RenderTexture.active=rt;var tex=new Texture2D(1800,1800,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1800,1800),0,0);tex.Apply();System.IO.File.WriteAllBytes("D:/67/CindersBackups/ModelResearch/poses.png",tex.EncodeToPNG());RenderTexture.active=old;camera.targetTexture=null;UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(tex);return "PASS 6 avatars; sampled every referenced clip; preview saved";}finally{UnityEngine.Object.DestroyImmediate(stage);}}
}

